package com.minimarket.producto.service.impl; import com.minimarket.common.exception.*; import com.minimarket.producto.dto.*; import com.minimarket.producto.entity.Marca; import com.minimarket.producto.repository.MarcaRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.cache.annotation.Cacheable; import org.springframework.cache.annotation.CacheEvict;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class MarcaServiceImpl implements com.minimarket.producto.service.MarcaService{private final MarcaRepository r; @Cacheable("marcas") public Page<MarcaResponseDTO> listar(Pageable p){return r.findAll(p).map(this::d);}public MarcaResponseDTO obtener(Long id){return d(f(id));}@Transactional @CacheEvict(value="marcas", allEntries=true) public MarcaResponseDTO crear(MarcaRequestDTO x){if(r.findByNombreIgnoreCase(x.nombre()).isPresent())throw new BusinessException("Marca ya existe");return d(r.save(Marca.builder().nombre(x.nombre().trim()).activo(true).build()));}@Transactional @CacheEvict(value="marcas", allEntries=true) public MarcaResponseDTO actualizar(Long id,MarcaRequestDTO x){Marca m=f(id);r.findByNombreIgnoreCase(x.nombre()).filter(a->!a.getId().equals(id)).ifPresent(a->{throw new BusinessException("Marca ya existe");});m.setNombre(x.nombre().trim());return d(m);}@Transactional @CacheEvict(value="marcas", allEntries=true) public void desactivar(Long id){f(id).setActivo(false);}private Marca f(Long id){return r.findById(id).orElseThrow(()->ResourceNotFoundException.of("Marca",id));}private MarcaResponseDTO d(Marca m){return new MarcaResponseDTO(m.getId(),m.getNombre(),m.getActivo(),m.getCreatedAt());}}